import { IDatabaseProvider, ITransaction, QueryResult } from '../../src/providers/IDatabaseProvider';
import { Dialect } from '../../src/core/types';
import { SqlTranslator } from '../../src/providers/translators/SqlTranslator';
import { translatorFor } from './translatorFor';

/** Alias of the shipped Dialect union, kept so existing tests keep their import. */
export type CaptureDialect = Dialect;

/**
 * Test provider that records every SQL statement (and its parameters) passed
 * to query() so unit tests can assert the exact SQL generated by
 * DbSet/QueryBuilder/DbContext for each dialect.
 *
 * It never talks to a real database. query() returns results from a
 * configurable queue (see nextResult) or a default result.
 *
 * Placeholder styles match the real providers exactly:
 * - postgresql: $1, $2, ...   (PostgreSQLProvider)
 * - mssql:      @p0, @p1, ... (MSSQLProvider, 1-based index -> 0-based name)
 * - mariadb:    ?             (MariaDBProvider)
 */
export class SqlCaptureProvider implements IDatabaseProvider {
    /** Every query() call, in order. */
    public calls: { sql: string; params?: any[] }[] = [];

    /** Result returned by query() when the queue is empty. */
    public defaultResult: QueryResult = { rows: [], rowCount: 1 };

    private resultQueue: QueryResult[] = [];

    constructor(private dialect: CaptureDialect) {}

    /** Queue a result to be returned by the next query() call. */
    nextResult(result: QueryResult): void {
        this.resultQueue.push(result);
    }

    /** Convenience accessor for the most recent query() call. */
    get lastCall(): { sql: string; params?: any[] } | undefined {
        return this.calls[this.calls.length - 1];
    }

    /** Clear recorded calls and queued results. */
    reset(): void {
        this.calls = [];
        this.resultQueue = [];
        this.transactionCalls = [];
        this.queryConnections = [];
        this.openTransactions = 0;
        this.failWhen = undefined;
        this.beginGate = undefined;
        this.rollbackError = undefined;
    }

    getDialect(): Dialect {
        return this.dialect;
    }

    getTranslator(): SqlTranslator {
        return translatorFor(this.dialect);
    }

    async connect(): Promise<void> {
        // no-op
    }

    async disconnect(): Promise<void> {
        // no-op
    }

    async query(text: string, params?: any[]): Promise<QueryResult> {
        return this.record('pool', text, params);
    }

    /**
     * Which connection ran each entry of `calls`: 'pool' for a plain
     * provider.query(), 'tx1', 'tx2', ... for a transaction handle.
     */
    public queryConnections: string[] = [];

    /** When set, a statement it returns an error for is recorded, then throws. */
    public failWhen?: (sql: string) => Error | undefined;

    private record(connection: string, text: string, params?: any[]): QueryResult {
        this.calls.push({ sql: text, params });
        this.queryConnections.push(connection);
        const failure = this.failWhen?.(text);
        if (failure) throw failure;
        return this.resultQueue.length > 0 ? this.resultQueue.shift()! : this.defaultResult;
    }

    /** Transaction lifecycle calls, in order, so tests can assert nesting. */
    public transactionCalls: ('begin' | 'commit' | 'rollback')[] = [];

    /** Handles begun and not yet committed or rolled back. */
    public openTransactions = 0;

    private transactionCount = 0;

    /** When set, beginTransaction() waits on it, so a test can overlap calls. */
    public beginGate?: Promise<void>;

    /** When set, a handle's rollback() records the call, then rejects with it. */
    public rollbackError?: Error;

    async beginTransaction(): Promise<ITransaction> {
        if (this.beginGate) await this.beginGate;
        this.transactionCalls.push('begin');
        this.openTransactions++;
        const id = `tx${++this.transactionCount}`;
        let open = true;
        const end = (call: 'commit' | 'rollback') => async () => {
            if (!open) return;
            open = false;
            this.transactionCalls.push(call);
            this.openTransactions--;
            if (call === 'rollback' && this.rollbackError) throw this.rollbackError;
        };
        return {
            id,
            get isOpen() {
                return open;
            },
            query: async (text: string, params?: any[]) => {
                if (!open) throw new Error('The transaction has already ended.');
                return this.record(id, text, params);
            },
            commit: end('commit'),
            rollback: end('rollback'),
        } as ITransaction & { id: string };
    }

    getParameterPlaceholder(index: number): string {
        switch (this.dialect) {
            case 'postgresql':
                return `$${index}`;
            case 'mssql':
                // Convert from 1-based caller convention to 0-based MSSQL binding
                return `@p${index - 1}`;
            case 'mariadb':
                return '?';
        }
    }

    mapType(tsType: string): string {
        return tsType;
    }

    normalizeType(dbType: string): string {
        return dbType.toLowerCase();
    }

    getAutoIncrementType(): string {
        return 'INTEGER';
    }

    isTypeMismatch(_entityType: string, _dbType: string): boolean {
        return false;
    }

    getSchemaColumnsQuery(tableName: string): { sql: string; params: any[] } {
        return {
            sql: `SELECT column_name, data_type FROM information_schema.columns WHERE table_name = ${this.getParameterPlaceholder(1)}`,
            params: [tableName],
        };
    }
}
